// Which interactable the prompt points at, and how its label reads on each device. SDK-free.

export interface Vec3 { x: number; y: number; z: number }
export type PromptButton = 'primary' | 'secondary'

export interface PromptVerb { verb: string; button: PromptButton }

export interface Placed { position: Vec3 | null; range?: number }

export const DEFAULT_RANGE = 2
// a thing on the floor below a balcony is not "near"
const MAX_HEIGHT_GAP = 2.5

export const KEY_LABEL: Record<PromptButton, string> = { primary: 'E', secondary: 'F' }

/** The closest candidate within its range of `from`, measured across the floor; null when none is. */
export function nearestCandidate<T extends Placed>(candidates: T[], from: Vec3 | null): T | null {
  if (from === null) return null
  let best: T | null = null
  let bestDistance = Infinity
  for (const candidate of candidates) {
    const at = candidate.position
    if (at === null || Math.abs(at.y - from.y) > MAX_HEIGHT_GAP) continue
    const distance = Math.hypot(at.x - from.x, at.z - from.z)
    if (distance > (candidate.range ?? DEFAULT_RANGE) || distance >= bestDistance) continue
    best = candidate
    bestDistance = distance
  }
  return best
}

/** Desktop names the key ("[E] Pick up"); a phone shows only the verb, its button is on screen. */
export function promptText(verbs: PromptVerb[], phone: boolean): string {
  const shown = verbs.filter((entry) => entry.verb.trim() !== '')
  if (phone) return shown.map((entry) => entry.verb).join(' · ')
  return shown.map((entry) => `[${KEY_LABEL[entry.button]}] ${entry.verb}`).join('   ')
}

/** A verb with the item's kind: "{item}" is replaced where the language wants it, otherwise the kind follows. */
export function verbWith(verb: string, kind: string): string {
  if (kind === '') return verb.replace(/\s*\{item\}\s*/g, ' ').trim()
  return verb.includes('{item}') ? verb.split('{item}').join(kind) : `${verb} ${kind}`.trim()
}
